<div><div class="card mb-3"><div class="card-header">Employee documents</div><div class="card-body"><form wire:submit="upload" class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">Employee</label><select class="form-select" wire:model="employeeId"><option value="">Select</option>@foreach($employees as $e)<option value="{{$e->id}}">{{$e->name}}</option>@endforeach</select></div><div class="col-md-2"><label class="form-label">Category</label><input class="form-control" wire:model="category"></div><div class="col-md-2"><label class="form-label">Expiry</label><input type="date" class="form-control" wire:model="expiresAt"></div><div class="col-md-3"><label class="form-label">File</label><input type="file" class="form-control" wire:model="file"></div><div class="col-md-2"><button class="btn btn-primary w-100">Upload</button></div></form>@error('file')<div class="text-danger mt-2">{{$message}}</div>@enderror</div></div><div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Employee</th><th>Category</th><th>File</th><th>Size</th><th>Expiry</th><th>SHA-256</th><th></th></tr></thead><tbody>@foreach($documents as $d)<tr><td>{{$d->employee->name}}</td><td>{{$d->category}}</td><td><a href="{{route('documents.download',$d)}}">{{$d->original_name}}</a></td><td>{{number_format($d->size_bytes/1024,1)}} KB</td><td>{{$d->expires_at?->toDateString()?:'—'}}</td><td><code>{{substr($d->sha256,0,12)}}…</code></td><td><button wire:click="delete({{$d->id}})" class="btn btn-sm btn-outline-danger">Delete</button></td></tr>@endforeach</tbody></table></div></div></div>
